$ErrorActionPreference = 'Stop'
# Only remove files generated by LANadd. Preserve user files and directory links.
function Test-PlainDirectory([string]$Path) {
    $item = Get-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue
    return $item -and $item.PSIsContainer -and -not ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)
}
function Clear-Payload([string]$Path) {
    if (!(Test-PlainDirectory $Path)) { return }
    foreach ($entry in Get-ChildItem -LiteralPath $Path -Force -File) {
        if ($entry.Name -match '^(Kyber\.dll|vivoxsdk\.dll|ca_root\.pem|VanillaBundleAggregation\.kb|VERSION|LAN-ADD-VERSION|LAN-MODULE|ONLINE-COMPATIBILITY\.json|(msvcp140(_[a-z0-9_]+)?|vcruntime140(_[a-z0-9_]+)?|vccorlib140|concrt140)\.dll)$' -and
            !($entry.Attributes -band [IO.FileAttributes]::ReparsePoint)) {
            Remove-Item -LiteralPath $entry.FullName -Force
        }
    }
    if (!(Get-ChildItem -LiteralPath $Path -Force)) { [IO.Directory]::Delete($Path) }
}
$baseDir = Join-Path $env:ProgramData 'Kyber'
$lanDir = Join-Path $baseDir 'LAN-Modules'
if (!(Test-PlainDirectory $baseDir) -or !(Test-PlainDirectory $lanDir)) { return }
$online = Join-Path $lanDir 'online'
if (Test-PlainDirectory $online) {
    foreach ($dir in Get-ChildItem -LiteralPath $online -Directory -Force) {
        if ($dir.Name -match '^(localized-[a-f0-9]{64}-[a-f0-9]{64}|[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12})$') {
            Clear-Payload $dir.FullName
        }
    }
    foreach ($name in 'ACTIVE','update.lock') {
        $marker = Join-Path $online $name
        if (Test-Path -LiteralPath $marker -PathType Leaf) { Remove-Item -LiteralPath $marker -Force }
    }
    if (!(Get-ChildItem -LiteralPath $online -Force)) { [IO.Directory]::Delete($online) }
}
foreach ($dir in Get-ChildItem -LiteralPath $lanDir -Directory -Force) {
    if ($dir.Name -match '^[a-f0-9]{64}$') { Clear-Payload $dir.FullName }
}
